{
  "name": "backeer-opencode",
  "version": "0.16.0",
  "description": "Backeer mobile approvals and authenticated live OpenCode control over SSE and MCP",
  "type": "module",
  "main": "./src/index.js",
  "exports": {
    ".": "./src/index.js",
    "./live-control-client": "./src/live-control-client.js",
    "./live-profiles": "./src/live-profiles.js",
    "./live-session-manager": "./src/live-session-manager.js",
    "./live-managed-mcp": "./src/live-managed-mcp.js",
    "./live-discovery": "./src/live-discovery.js",
    "./tui": "./src/opencode-v2-tui.js"
  },
  "bin": {
    "backeer-opencode": "bin/backeer-opencode.js",
    "backeer-opencode-mcp": "bin/backeer-opencode-mcp.js"
  },
  "files": [
    "src",
    "dist",
    "bin",
    "README.md",
    "CHANGELOG.md",
    "LICENSE",
    "docs",
    "scripts/check-package.mjs"
  ],
  "scripts": {
    "build": "esbuild src/index.js --bundle --platform=node --format=esm --target=node18 --outfile=dist/backeer-permission.js --legal-comments=none",
    "check": "npm run lint && node --check bin/backeer-opencode.js && node --check bin/backeer-opencode-mcp.js && npm test",
    "lint": "eslint src bin test eslint.config.js --max-warnings=0",
    "pretest": "npm run build",
    "test": "node --test",
    "pack:check": "npm pack --dry-run",
    "publish:check": "npm publish --dry-run --access public",
    "prepack": "npm run build",
    "prepublishOnly": "npm run check && npm run check:package",
    "check:package": "node scripts/check-package.mjs",
    "test:reliability": "node --test test/live-reliability.test.mjs test/live-control-e2e.test.mjs test/live-session-manager.test.mjs",
    "audit:production": "npm audit --omit=dev --audit-level=moderate",
    "audit:all": "npm audit --audit-level=moderate",
    "test:runtime": "node --test"
  },
  "keywords": [
    "backeer",
    "opencode",
    "plugin",
    "notifications"
  ],
  "engines": {
    "node": ">=18"
  },
  "author": {
    "name": "Backeer",
    "email": "hello@backeer.com",
    "url": "https://backeer.com/"
  },
  "homepage": "https://backeer.com/",
  "bugs": {
    "email": "hello@backeer.com"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "1.32.2",
    "@opencode/client": "2.0.26",
    "zod": "4.6.7"
  },
  "devDependencies": {
    "@eslint/js": "^10.0.1",
    "esbuild": "^0.28.2",
    "eslint": "^10.14.0",
    "globals": "^16.5.0"
  },
  "license": "SEE LICENSE IN LICENSE",
  "overrides": {
    "minimatch": "^11.0.1"
  },
  "peerDependencies": {
    "@opentui/solid": ">=0.5.10",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  }
}
